.stock-page:before{content:"";position:absolute;inset:0;z-index:-3;background:linear-gradient(90deg,rgba(112,79,67,.025) 1px,transparent 1px),linear-gradient(rgba(112,79,67,.025) 1px,transparent 1px);background-size:34px 34px;mask-image:linear-gradient(to bottom,#000,transparent 80%)}
.page-glow{position:absolute;z-index:-2;border-radius:50%;pointer-events:none;filter:blur(1px)}.glow-one{width:420px;height:420px;right:-170px;top:90px;background:rgba(196,111,61,.08)}.glow-two{width:320px;height:320px;left:-190px;bottom:120px;background:rgba(112,79,67,.07)}
.stock-header,.metrics,.alert-banner,.notice,.inventory-card,.history-card,.analytics-card{width:min(1260px,100%);margin-left:auto;margin-right:auto}
.stock-header{display:flex;justify-content:space-between;align-items:flex-end;gap:32px;margin-bottom:26px}.eyebrow{display:block;margin:0 0 8px;color:#b76538;font-size:9px;font-weight:900;letter-spacing:2.2px}.stock-header h1{margin:0;color:#382923;font:700 clamp(31px,3.7vw,44px)/1.05 Georgia,serif;letter-spacing:-.8px}.stock-header>div:first-child{max-width:700px}.stock-header p{margin:10px 0 0;color:#88756c;font-size:12px;line-height:1.65}
.header-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.search{display:flex;align-items:center;gap:9px;width:300px;height:43px;padding:0 13px;box-sizing:border-box;border:1px solid #ded4cc;border-radius:12px;background:rgba(255,255,255,.88);box-shadow:0 6px 18px rgba(67,47,38,.05)}.search span{color:#b76538;font-size:17px}.search input{width:100%;border:0;outline:0;background:transparent;color:#4b3932;font-size:11px}.primary{display:inline-flex;align-items:center;justify-content:center;min-height:43px;padding:0 17px;border:0;border-radius:12px;background:#68483e;color:#fff;font-size:11px;font-weight:800;text-decoration:none;box-shadow:0 8px 18px rgba(104,72,62,.18);transition:.18s ease}.primary:hover{background:#563a32;transform:translateY(-1px)}
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.metrics article{position:relative;overflow:hidden;min-height:112px;padding:19px 20px;border:1px solid #e1d7cf;border-radius:16px;background:rgba(255,255,255,.82);box-shadow:0 12px 32px rgba(67,47,38,.065);backdrop-filter:blur(10px)}.metrics article:after{content:"";position:absolute;right:-22px;top:-25px;width:80px;height:80px;border-radius:50%;background:rgba(196,111,61,.07)}.metrics span,.metrics small{display:block;color:#8b7970;font-size:10px}.metrics strong{display:block;margin:8px 0 4px;color:#46342d;font:700 30px Georgia,serif}.metrics .green{color:#3f7e5e}.metrics .amber{color:#ad762d}.metrics .red{color:#b55249}
.alert-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;box-sizing:border-box;margin-bottom:14px;padding:14px 17px;border:1px solid #ead7c2;border-radius:13px;background:linear-gradient(90deg,#fff8ef,#fffaf6);box-shadow:0 6px 18px rgba(120,82,45,.05)}.alert-banner strong{display:block;color:#87591f;font-size:11px}.alert-banner span{display:block;margin-top:4px;color:#9b8067;font-size:10px}.alert-banner button{border:1px solid #dcbf9e;border-radius:9px;padding:8px 13px;background:#fff;color:#965f2b;font-size:10px;font-weight:800;cursor:pointer}.notice{box-sizing:border-box;margin-bottom:14px;padding:12px 15px;border-radius:10px;font-size:11px;font-weight:700}.notice.success{border:1px solid #cfe1d5;background:#f0f8f2;color:#397052}.notice.error{border:1px solid #edcfca;background:#fff3f1;color:#a34e47}
